<script setup>defineProps({open:Boolean});defineEmits(['confirm','cancel'])</script>
<template><Teleport to="body"><Transition name="modal"><div v-if="open" class="modal-backdrop" @click.self="$emit('cancel')"><div class="confirm-dialog" role="alertdialog" aria-modal="true" aria-labelledby="confirm-title"><div class="dialog-icon">⌫</div><h2 id="confirm-title">删除这条记录吗？</h2><p>删除后无法恢复，但不会影响其他记录。</p><div><button class="secondary-button" type="button" @click="$emit('cancel')">再想想</button><button class="danger-button" type="button" @click="$emit('confirm')">确认删除</button></div></div></div></Transition></Teleport></template>
